window.VIDYA_HINDI = [
{title:'उच्चतर विद्या',summary:'विद्या उस ज्ञान का नाम है जो विश्व के आधारभूत अनादि आध्यात्मिक सत्य को प्रकाशित करता है। ऋषि करुणा से अपना अनुभव बाँटकर दूसरों में अंतःपूर्णता जगाते हैं। अध्याय चार वेद और मंत्र, ब्राह्मण, आरण्यक तथा उपनिषद् का परिचय देता है। उपनिषद् वैदिक खोज की पूर्णता हैं, जो बाहरी अभ्यास और भीतरी समझ में सामंजस्य लाते हैं। उपनिषद्, ब्रह्मसूत्र और भगवद्गीता दार्शनिक अध्ययन के प्रस्थानत्रयी हैं।\n\nभौतिक और अभौतिक जगत एक अखंड चेतना की अभिव्यक्तियाँ हैं। शिक्षा यह एकता प्रकट करके ममता और अहंकार से मुक्त करे। इसके लिए उचित कर्तव्य छोड़ना नहीं; अनासक्ति, कृतज्ञता और परिणामों की समझ से कर्म करना है। आध्यात्मिक मूल्य इस बात से परखें कि कर्म बंधन घटाता या लोभ बढ़ाता है। आत्मा अविकारी, सर्वव्यापी और सामान्य वर्णन से परे है। उच्चतम समझ में विरोधी लगते भेद एक सत्य की अनुभूति में पार होते हैं, केवल पाठ्यज्ञान नहीं रहते।',quiz:[
['इस अध्याय में विद्या का मूल अर्थ क्या है?',['प्रकाशित करने वाला ज्ञान','धन की गारंटी देने वाला ज्ञान','केवल सार्वजनिक तर्क का कौशल','उपाधियों का संग्रह'],'विद्या केवल जानकारी नहीं बढ़ाती, परम आध्यात्मिक तत्त्व प्रकट करती है।'],
['प्रस्थानत्रयी कौन-से ग्रंथ हैं?',['ऋग्वेद, सामवेद और यजुर्वेद','उपनिषद्, ब्रह्मसूत्र और भगवद्गीता','रामायण, महाभारत और मनुस्मृति','ब्राह्मण, आरण्यक और पुराण'],'अध्याय इन तीन को प्रस्थानत्रयी कहता है।'],
['कौन-सा वैदिक भाग विशेषतः भीतरी अनुशासन और अर्थ बताता है?',['केवल ब्राह्मण','केवल कर्मकांड के सूत्र','आरण्यक','केवल स्तुतियाँ'],'आरण्यक भीतरी अर्थ, इंद्रियों की निवृत्ति और आसक्तिमुक्ति से जुड़े हैं।'],
['उचित सांसारिक कर्तव्य कैसे करें?',['बढ़ती ममता से','केवल प्रशंसा के लिए','परिणामों की परवाह बिना','अनासक्ति और समझ से'],'शिक्षा उलझाव बिना उत्तरदायी कर्म की है।'],
['पवित्र कर्म परखने की कसौटी क्या है?',['वह आसक्ति बढ़ाने के बजाय बंधन से बचाता है या नहीं','तुरंत यश देता है या नहीं','महँगी सामग्री चाहिए या नहीं','बहुत लोग देखते हैं या नहीं'],'कर्म आसक्ति और लोभ से संबंध के आधार पर परखा गया है।']]},
{title:'आत्मज्ञान',summary:'आध्यात्मिक ज्ञान पाने और देने के लिए शुद्ध मन चाहिए। अशुद्ध हृदय हानिकारक जीवों के स्थान जैसा और अज्ञान ऐसा अंधकार है जो केवल प्रकाश से हटता है। धोने से कोयला वैसा नहीं बदलता जैसा अग्नि से; आत्मबोध भी सतही उपायों से अछूते दोष बदलता है। यह ज्ञान खरीदा या उधार नहीं लिया जा सकता; श्रद्धा, भक्ति और निजी प्रयत्न से आत्मसात् करें। ईश्वर कहीं नहीं से ईश्वर अभी यहीं हैं की दृष्टि एकता का बोध दिखाती है।\n\nसंतों का जीवन ऐसे पांडित्य से अलग है जो आचरण नहीं बदलता। सच्ची समझ विचार, वाणी और कर्म में मेल लाती है। दोष पहचानकर उपयोगी सुधार स्वीकारें, केवल अनुपालित सलाह से संतुष्ट न हों। शक्कर का जल और सादा जल दिखने में समान, स्वाद में अलग हैं; अनुभूत ज्ञान और शब्दविद्या भी अलग हैं। गीली दियासलाई विषयकामना से भरे हृदय के निष्प्रभावी उपदेश की उपमा है। अंत में बाहरी जानकारी से अलग भीतरी ज्ञान मन शुद्ध करता और हृदय की दृष्टि बढ़ाता है।',quiz:[
['आध्यात्मिक ज्ञान का अर्थ खुलने के लिए क्या चाहिए?',['उपाधियों का बड़ा संग्रह','केवल महँगा समारोह','हर श्रोता की स्वीकृति','शुद्ध मन'],'उच्च विद्या ग्रहण और संप्रेषित करने की शर्त पवित्रता है।'],
['उदाहरण में कोयले को सफेद राख क्या बनाता है?',['अग्नि','केवल साबुन','दूध','ठंडा जल'],'अग्नि अज्ञान पर आत्मज्ञान की परिवर्तनकारी शक्ति दर्शाती है।'],
['ईश्वर कहीं नहीं से अभी यहीं हैं की दृष्टि क्या दिखाती है?',['ईश्वर को भौतिक रूप से लाना पड़ेगा','बदली दृष्टि दिव्य उपस्थिति खोल सकती है','केवल भाषा अभ्यास की जगह लेती है','भेद हमेशा बढ़ाने चाहिए'],'उदाहरण निषेध को उपस्थिति की पहचान में बदलता है।'],
['शक्कर के जल और सादे जल की तुलना किसका भेद है?',['मुक्ति के दो समान रूप','धन और गरीबी','अनुभूत ज्ञान और मात्र शास्त्रीय विद्वत्ता','दो प्रकार के शारीरिक बल'],'बाहरी समानता प्रत्यक्ष अनुभव से ज्ञात भेद नहीं मिटाती।'],
['यहाँ महात्मा का प्रमुख लक्षण क्या है?',['दोष छिपाने का कौशल','निरंतर परनिंदा','केवल लाभ के लिए ज्ञान','विचार, वचन और कर्म में सामंजस्य'],'भीतरी शुद्धि वाणी और कर्म में समान दिखती है।']]},
{title:'आधुनिक शिक्षा',summary:'अध्याय खर्च और जटिलता बढ़ाते हुए नैतिक प्रशिक्षण भूलने वाली शिक्षा की आलोचना करता है। इसकी तुलना पुराने गुरुकुल आदर्श के अनुशासन, विनम्रता और इंद्रियसंयम से है। शिक्षक का दायित्व केवल सूचना देना नहीं, विद्यार्थियों का कल्याण और निर्माण है। फिर एक ही संसार के भिन्न अनुभव समझाए गए हैं: संबंध के अनुसार एक व्यक्ति पिता, पुत्र, पति या मित्र दिखता है। विवेकी दृष्टि सृष्टि की समझ बदलती है।\n\nनारायण और लक्ष्मी की कथा लोभ द्वारा आध्यात्मिक मूल्य पीछे होने को दिखाती है। नारायण विद्वान शिक्षक बनकर उत्सुक श्रोता जुटाते हैं। लक्ष्मी तपस्विनी बनकर मेजबानों के यहाँ सोने की थालियाँ और प्याले छोड़ती हैं। जब वे आने की शर्त विद्वान को हटाना रखती हैं, लोग सोने के लोभ में उसे निकाल देते हैं। विद्या का दिखता सम्मान धन की अधिक आसक्ति छिपा सकता है। ज्ञान नैतिक-आध्यात्मिक विकास के बजाय मुख्यतः आर्थिक लाभ का माल बने तो शिक्षा उद्देश्य खो देती है।',quiz:[
['आधुनिक शिक्षा की मुख्य कमी क्या बताई गई है?',['महँगी व्यवस्था','जटिल संगठन','नैतिक शिक्षा','भौतिक उन्नति में रुचि'],'आलोचना विनम्रता, सद्गुण, अनुशासन और इंद्रियसंयम की उपेक्षा पर है।'],
['एक व्यक्ति को लोग अलग क्यों देखते हैं?',['वह हर दर्शक के लिए शरीर बदलता है','कोई किसी को पहचान नहीं सकता','सबकी भावनाएँ समान हैं','संबंध और प्रतिक्रिया उनकी दृष्टि बनाते हैं'],'पिता, पुत्र, पति और मित्र का उदाहरण दृष्टिकोण का प्रभाव दिखाता है।'],
['कथा में नारायण कौन-सा रूप लेते हैं?',['प्रसिद्ध विद्वान','गाँव के व्यापारी','राजरक्षक','घूमता संगीतकार'],'उनकी विद्या और प्रवचन पहले व्यापक सम्मान पाते हैं।'],
['लक्ष्मी मेजबानों के पास क्या छोड़ती हैं?',['व्याकरण की पुस्तकें','सोने की थालियाँ और प्याले','लकड़ी का दंड','अनाज की बोरी'],'ये उपहार लोगों को विद्वान की घोषित प्रशंसा से दूर खींचते हैं।'],
['ग्रामवासी विद्वान को क्यों निकालते हैं?',['उन्हें पता चलता है वह बोल नहीं सकता','वह हर चर्चा मना करता है','वे तपस्विनी के स्वर्ण उपहार चाहते हैं','उन्होंने भौतिक फल त्याग दिए हैं'],'कथा ज्ञान के बाहरी सम्मान के नीचे लोभ खोलती है।']]},
{title:'मूल अज्ञान का निवारण',summary:'अध्याय सर्वकल्याण से शुरू होकर गर्व और अहंकार को ज्ञान की बाधाएँ बताता है। पार्वती के तप और मन्मथ-दहन का प्रतीकात्मक अर्थ है: आत्ममहत्त्व रहते बाहरी सुंदरता और शक्ति से दिव्यता नहीं मिलती। आध्यात्मिक विद्या विनम्रता, सहिष्णुता और अनुशासन में दिखती है। घटना अहंभाव के परिवर्तन और मिलन या मुक्ति की पूर्णता की ओर संकेत करती है।\n\nदूसरा प्रमुख गुण वैराग्य है। वास्तविक त्याग भीतर, विशेषतः इच्छा का त्याग है; केवल घर या संपत्ति छोड़ना नहीं। घड़े का जल निकालने से आकाश का प्रतिबिंब हटता है, वास्तविक आकाश रहता है—गलत पहचान हटने पर शेष सत्य की उपमा। इच्छा अज्ञान से उठती है और क्रोध-लोभ पीछे आते हैं। मानव जीवन मार्गदर्शन समझकर प्रयत्न और शिक्षा से प्रवृत्तियाँ बदलने की क्षमता देता है; इंद्रियसंयम आवश्यक है। अंत में सच्ची विद्या से विनम्रता, योग्य कर्म की पात्रता, समृद्धि, दान, धर्म और सुख का क्रम है।',quiz:[
['यहाँ मन्मथ की घटना क्या दर्शाती है?',['शारीरिक सुंदरता की सर्वोच्चता','दिव्य ज्ञान चमकने से पहले अहंकार का नाश','भक्ति पर आर्थिक बल का महत्त्व','सभी अनुशासन का निषेध'],'कथा बाहरी आकर्षण की विजय नहीं, भीतरी परिवर्तन है।'],
['वास्तविक त्याग क्या है?',['केवल निवास बदलना','दान का प्रदर्शन','इच्छा छोड़ना','हर जिम्मेदारी छोड़ना'],'निर्णायक परिवर्तन मन के भीतर है।'],
['घड़े का जल निकालना क्या दर्शाता है?',['वास्तविक आकाश नष्ट करना','और संपत्ति पाना','ज्ञान की जगह अज्ञान','गलत पहचान हटाकर आत्मा को स्पष्ट रहने देना'],'प्रतिबिंब हटता है, वास्तविक आकाश रहता है।'],
['इच्छा का मूल स्रोत क्या है?',['अज्ञान','विनम्रता','विवेक','संतोष'],'इच्छा आगे विक्षोभ देती है; मूल अज्ञान का समाधान चाहिए।'],
['अंतिम क्रम में वास्तविक शिक्षा पहले क्या देती है?',['गर्व','विनम्रता','सार्वजनिक सत्ता','विषयभोग'],'विनम्रता योग्य कार्य और समृद्धि के सदुपयोग की तैयारी है।']]},
{title:'आध्यात्मिक अनुशासन',summary:'आध्यात्मिक शिक्षा बाहरी रूपों के नीचे सत्य खोजती है; उसे समझने के साथ जीना भी है। दर्शन ज्ञान का प्रेम है, जिसकी खोज कठिनाई में भी निष्ठा से हो। मनुष्य शरीर, मन और आत्मा तथा पशु, मानव और दिव्य प्रवृत्तियों से समझाया गया है। शिक्षा दिव्य स्वभाव का बोध जगाकर उद्देश्य पूरा करती है। यंत्र, वृक्ष और लघु विश्व की उपमाएँ शरीर का बड़ी आध्यात्मिक व्यवस्था में स्थान समझाती हैं।\n\nअच्छे-बुरे के निर्णय में विवेक चाहिए; दुःख करुणा जगा सकता है। विचार जीवन बनाते हैं, जबकि अपूर्ण भौतिक इच्छाएँ जन्म-मृत्यु का चक्र चलाती हैं। ईश्वर को जानने और प्रेम करने की इच्छा बंधनकारी इच्छाओं से अलग है। विद्या सद्विचार स्थिर करे और आसक्ति घटाए। मृत्यु देह की है, अविनाशी आत्मा की नहीं। अंत में राष्ट्र और धर्म के भेदों के नीचे एक दिव्य शक्ति सब जीवों में कार्य करती है। इस समान सत्य का ज्ञान अन्य मान्यताओं और विद्याओं को समझने का केंद्र है।',quiz:[
['दर्शन की परिभाषा क्या है?',['ज्ञान का प्रेम','केवल तर्क का प्रेम','उपाधियाँ पाने का कौशल','हर विचार का निषेध'],'यह निष्ठापूर्ण सत्यखोज से जुड़ा है।'],
['मनुष्य का कौन-सा त्रिविध स्वरूप बताया गया है?',['धन, पद और व्यवसाय','शरीर, मन और आत्मा','वाणी, वस्त्र और ख्याति','जन्म, यात्रा और निवृत्ति'],'शिक्षा गहरे दिव्य स्वरूप की पहचान जगाती है।'],
['कौन-सी इच्छा स्पष्टतः नहीं बाँधती?',['असीम संपत्ति की इच्छा','हर प्रतिद्वंद्वी हराने की इच्छा','ईश्वर को जानने और प्रेम करने की इच्छा','निरंतर इंद्रियसुख की इच्छा'],'दिव्य उत्कंठा भौतिक आसक्ति से अलग है।'],
['विचारों की क्या भूमिका है?',['आचरण पर कोई असर नहीं','विवेक की आवश्यकता हटाते हैं','वे सदा प्रशिक्षण से परे हैं','वे जीवन को आकार देते हैं'],'विद्या सद्विचारों को स्थिर स्थापित करे।'],
['देह की मृत्यु से क्या अप्रभावित रहता है?',['आत्मा','देह का अस्थायी रूप','हर अपूर्ण भौतिक योजना','शारीरिक रूप'],'आत्मा देह के विनाश के अधीन नहीं, अविनाशी है।']]},
{title:'आध्यात्मिक गुरु',summary:'विचार, भाव और कर्म वर्तमान-भविष्य की दशाएँ बनाते हैं, साथ ही दूसरों की सहायता का महत्त्व है। प्रगति के लिए तेज बुद्धि या प्रभावी भाषण पर्याप्त नहीं; अंतर्जीवन विकसित और मन शुद्ध होने पर विद्या फलती है। योग्य गुरु का जीवंत संपर्क वह प्रेरणा दे सकता है जो केवल पढ़ना नहीं देता। गुरु में अनुभूत आत्मसत्य और शिष्य में सच्ची उत्सुकता तथा ग्रहणशीलता हो। जीवंत बीज और तैयार खेत उनकी पूरक पात्रता की उपमा हैं।\n\nअवतार आध्यात्मिक शक्ति जगाने की विशेष क्षमता वाले शिक्षक बताए गए हैं। जीव अपने स्वभाव के अनुसार ईश्वर का रूप कल्पित करता है। समुद्र से भरे अलग पात्रों में एक जल अलग आकार और मात्रा में होता है—विभिन्न धारणाओं के नीचे एक दिव्यता है। इंद्रियानुभव तक सीमित तर्क सर्वव्यापकता या सर्वशक्तिमत्ता पूरी नहीं पकड़ सकता। इसलिए आध्यात्मिक शिक्षा सत्य का भीतरी अनुभव और बोध है, अननुभूत बात पर वाक्पटुता या अनुमान नहीं।',quiz:[
['केवल बौद्धिक विद्या अपर्याप्त क्यों है?',['वह मार्गदर्शन की जरूरत हमेशा मिटाती है','वह पूर्ण ज्ञान की गारंटी है','वह हर वक्ता को सिद्ध गुरु बनाती है','वह आवश्यकतः अंतर्जीवन नहीं बदलती'],'बौद्धिक क्षमता और भीतरी विकास अलग हैं।'],
['गुरु की पात्रता क्या हो?',['हृदय में स्थापित आत्मसत्य','केवल शुल्क जुटाने का कौशल','केवल ख्याति','हर विवाद जीतना'],'अनुभूति गुरु के अधिकार का आधार है, रूप या वाक्पटुता नहीं।'],
['तैयार खेत क्या दर्शाता है?',['गुरु का धन','ग्रहणशील शिष्य','श्रोताओं की संख्या','पुस्तक संग्रह'],'आध्यात्मिक फसल के लिए जीवंत बीज और उचित खेत दोनों चाहिए।'],
['एक समुद्र से भरे भिन्न पात्र क्या दर्शाते हैं?',['असंबंधित परम सत्य','सत्य पर भौतिक रूप की श्रेष्ठता','एक दिव्य सत्य रखने वाली भिन्न धारणाएँ','दिव्य बोध की असंभवता'],'जीव अपनी क्षमता और प्रकृति के अनुसार ग्रहण और कल्पना करता है।'],
['अंत में आध्यात्मिक शिक्षा क्या है?',['केवल प्रिय भाषण','समझ बिना दोहराव','दूसरे की उपलब्धि पर बहस','सत्य का अनुभव और बोध'],'उसकी पूर्णता अंतरतम में है।']]},
{title:'धर्म की संस्कृति',summary:'मानव विकास को जीविका के साधन और जीवन के लक्ष्य दोनों का ज्ञान चाहिए। सांसारिक कौशल दैनिक जरूरतें पूरा करते हैं; गहरी खोज पूछती है कि हम कौन हैं, क्यों जीते हैं और पूर्णता क्या है। अनुशासन इंद्रियों से परे विश्व में एक सत्य की पहचान की ओर ले जाता है। सच्ची शिक्षा हितकारी संबंध और सामाजिक आचरण बनाती है। शिक्षकों का चरित्र और आदतें बच्चों पर गहरा असर डालते हैं, इसलिए विशेष उत्तरदायित्व है।\n\nश्रवण और हरिश्चंद्र की कथाओं से गांधी की प्रेरणा श्रेष्ठ उदाहरणों की निर्माणकारी शक्ति दिखाती है। वेद कर्तव्य और नैतिक मार्गदर्शन का स्रोत हैं। शिक्षा पूर्ण करने वालों को माता, पिता और गुरु का आदर, सत्यवचन और धर्माचरण की सलाह है। धर्मव्याध, राम, हरिश्चंद्र और बुद्ध सेवा, सत्य और अहिंसा के उदाहरण हैं। सिद्धांत केवल औपचारिक शब्द नहीं, जीवन का अनुशासन बनें। मन को विशेषतः काम और क्रोध से बचाएँ, जिनके पीछे अन्य विकार आते हैं। आध्यात्मिक विद्या इस प्रशिक्षण के अभ्यास देती है।',quiz:[
['मानव विकास को कौन-से दो ज्ञान चाहिए?',['केवल धन और यश','वस्त्र और मनोरंजन','जीविका और जीवन के लक्ष्य का ज्ञान','होड़ और सत्ता'],'जीवनयापन के साधन और अंतिम उद्देश्य अलग हैं।'],
['शिक्षक का चरित्र विशेष महत्त्वपूर्ण क्यों है?',['चरित्र सीखने पर असर नहीं करता','केवल परीक्षा-फल महत्त्वपूर्ण हैं','शिक्षक केवल वयस्क प्रभावित करते हैं','विद्यार्थी उनकी आदतें और उदाहरण ग्रहण करते हैं'],'शिक्षक पीढ़ियों से समाज को आकार देते हैं।'],
['बालक गांधी को कौन-सी दो कथाएँ प्रभावित करती हैं?',['श्रवण और हरिश्चंद्र','कंस और जरासंध','दुर्वासा और अंबरीष','नारायण और लक्ष्मी'],'इनसे मातृ-पितृभक्ति और अटल सत्य की प्रेरणा मिली।'],
['अध्ययन पूरा करने वालों को क्या निर्देश था?',['हर लक्ष्य से ऊपर धन','सत्य बोलो और धर्म का आचरण करो','माता-पिता और गुरु की उपेक्षा','हर सामाजिक दायित्व से बचो'],'सलाह नैतिक आचरण को जीवन के मार्गदर्शकों के आदर से जोड़ती है।'],
['कौन-से दो शत्रु अन्य चार को साथ लाते हैं?',['विनम्रता और धैर्य','श्रद्धा और भक्ति','काम और क्रोध','सत्य और अहिंसा'],'इन विकारों को जमने से रोकने के लिए अनुशासन पर बल है।']]},
{title:'प्रेमपूर्ण सेवा',summary:'लाभ की इच्छा बिना प्रेम या कर्तव्य से किया काम योग है। दूसरों को आत्मबंधु मानकर सेवा स्वार्थ घटाती और आत्मबोध गहराती है। शिक्षा के केंद्र में सेवा की प्रेरणा है। धन, कौशल, बुद्धि और पद मानव कल्याण में उचित उपयोग पाते हैं। सेवा भीतरी सद्भाव व्यक्त करे; भलाई के नाम पर कभी हानि, पीड़ा या शोक न दे।\n\nप्रतिफल की अपेक्षा बिना अर्पित हर कर्म पूजा बन सकता है। सेवा प्रेम का फूल और अहानिकरता उसकी सुगंध है। पहले आत्मपरिवर्तन करें, फिर दूसरों की सहायता; चिंता सीमित समूह या राष्ट्र से आगे समस्त मानवता तक हो। विनम्रता सीखने देती है और कठिनाई संकल्प बढ़ा सकती है। साझा दिव्यता के कारण घृणा आत्मघाती है। अंत में हृदय को दिव्यता, विनम्रता और उदारता से सँवारने तथा विवेक, आत्मसंयम, श्रद्धा, भक्ति और धैर्य की औषधि-पेटी का प्रतीक है। ये अज्ञान दूर करके शक्ति रचनात्मक सेवा में लगाते हैं।',quiz:[
['यहाँ किस काम को योग कहा है?',['केवल तालियों के लिए','लाभ की इच्छा बिना प्रेम या कर्तव्य से किया कार्य','हर जिम्मेदारी से बचता कार्य','स्वार्थ बढ़ाता कार्य'],'आध्यात्मिक मूल्य प्रेरणा और अर्पण में है।'],
['शिक्षा का हृदय क्या है?',['अधिकार जमा करना','मान्यता की होड़','निःस्वार्थ सेवा का आदर्श और अभ्यास','केवल नारे रटना'],'प्रेम की सेवा में अभिव्यक्ति शिक्षा की पूर्णता है।'],
['सेवा के फूल की सुगंध क्या है?',['गर्व','पुरस्कार','होड़','अहानिकरता'],'सच्ची सेवा ऐसी देखभाल है जो चोट न दे।'],
['दूसरों के सुधार से पहले क्या हो?',['अपना परिवर्तन','सरकारी उपाधि पाना','सबकी प्रशंसा लेना','समाज की चिंता छोड़ना'],'पहले समझ को भीतर लागू करें।'],
['विद्यार्थी की प्रतीकात्मक औषधि-पेटी के तीन चूर्ण कौन-से हैं?',['धन, सुंदरता और शक्ति','श्रद्धा, भक्ति और धैर्य','क्रोध, गर्व और महत्वाकांक्षा','यश, आराम और अधिकार'],'विवेक और आत्मसंयम के साथ ये अज्ञान का रोग दूर करते हैं।']]},
{title:'विचार, वाणी और कर्म की शुद्धि',summary:'आध्यात्मिक शिक्षा गहराई से ग्रहण करने के लिए श्रद्धा और पवित्रता चाहिए। सँवरा हृदय खेती की तैयार भूमि जैसा है, जिसमें आत्मज्ञान का बीज बढ़ता है। केवल सुनना पर्याप्त नहीं; मनन, अनुभव और विचार-वाणी-कर्म में अभिव्यक्ति चाहिए। हानिकारक इच्छाएँ और क्रोध घटने पर आत्मविश्वास स्थिर होता है। माला के धागे, सुई और फूल से भक्ति, वैराग्य और एकाग्रता का मेल समझाया गया है।\n\nकृष्ण-अर्जुन के उदाहरण से दिव्य शरण और साहसी पवित्रता का संयोग विजय है। सांसारिक सफलता छाया जैसी है: पीछा करो तो दूर जाती, सूर्य की ओर मुड़ो तो पीछे चलती है। ध्यान माया से दिव्यता की ओर मोड़ें। स्वर्ण पिंजरे का तोता सुख-सुविधा और स्वतंत्रता का अंतर बताता है। राजसी देखभाल और अच्छा भोजन होते हुए भी वह अपने वन को चाहता है। विलास इंद्रियबंधन नहीं हटाता। आत्मपहचान वास्तविक आध्यात्मिक स्वतंत्रता की उत्कंठा जगाए।',quiz:[
['अच्छी जोती भूमि क्या दर्शाती है?',['ज्ञान के लिए तैयार शुद्ध हृदय','धनी घर','मनोरंजन के श्रोता','विरोधी इच्छाओं वाला मन'],'समझ के बीज को उचित भीतरी तैयारी चाहिए।'],
['आध्यात्मिक सलाह सुनने के बाद क्या हो?',['तुरंत पूर्ण ज्ञान का दावा','मनन, अनुभव और आचरण में अभिव्यक्ति','ध्यान बिना दोहराव','हर दूसरे श्रोता की आलोचना'],'शिक्षा सुनी बात नहीं, जीया सत्य बने।'],
['माला की उपमा में सुई क्या है?',['भक्ति','धन','अनासक्ति','सार्वजनिक मान्यता'],'भक्ति धागा, अनासक्ति सुई और स्थिर ध्यान फूल हैं।'],
['सूर्य की ओर मुड़ने पर छाया क्या करती है?',['सूर्य बनती है','उसे और तेज दौड़ना पड़ता है','सभी दिशा असंभव होती है','पीछे चलती है'],'उदाहरण सांसारिक भ्रम के पीछे दौड़ने के बजाय ईश्वर की ओर मोड़ता है।'],
['राजसी तोता दुखी क्यों है?',['वह अपने वन की स्वतंत्रता चाहता है','उसे भोजन नहीं','पिंजरा पर्याप्त मूल्यवान नहीं','रानी कभी देखभाल नहीं करती'],'आराम और आदर कैद की भरपाई नहीं करते।']]},
{title:'आध्यात्मिकता की आवश्यकता',summary:'तकनीकी उन्नति के साथ संघर्ष, होड़ और नैतिक अव्यवस्था क्यों बने हैं? बहुत शास्त्र, गुरु और संस्थाएँ स्वयं शांति क्यों नहीं लाते? उत्तर अपरिवर्तित प्रेरणाओं में है: घृणा, ईर्ष्या, लोभ और श्रेष्ठता का प्रदर्शन मार्गदर्शक होने का दावा करने वालों को भी दूषित करते हैं। उपाय विशेषतः युवाओं में मन-हृदय की पवित्रता है, केवल नया बाहरी तंत्र नहीं। मात्र संग्रह और नैतिक नारों की जगह ब्रह्मज्ञान आए।\n\nअस्थायी रूप और शाश्वत सत्य अलग हैं। मिट्टी का घड़ा कुछ समय नाम-रूप रखकर भी मिट्टी पर निर्भर है; देह और सांसारिक व्यवस्थाएँ भी उठती-मिटती हैं। उन्हें पूर्णता का अंतिम स्रोत मानना आत्मा से ध्यान हटाता है। दूर के पहाड़ और मृगतृष्णा बताते हैं कि विवेक से जाँचने तक आकर्षण भटका सकता है। स्थायी सुख क्षणिक वस्तु या अनुभव में नहीं, आध्यात्मिक सत्य में है। आत्मविद्या सीखना और जीना अपनी तथा दूसरों की आध्यात्मिक प्यास बुझाने का साधन है।',quiz:[
['अध्याय किस विरोधाभास से शुरू होता है?',['शिक्षा और संस्थाओं का पूर्ण अभाव','बिना प्रयत्न विश्वशांति','सभी भौतिक ज्ञान का लोप','तकनीकी प्रगति के साथ नैतिक अव्यवस्था और संघर्ष'],'बाहरी विकास ने मानव प्रेरणाएँ स्वतः नहीं बदलीं।'],
['आवश्यक उपाय कहाँ है?',['पवित्रता से भरे मन और हृदय में','केवल बाहरी पुनर्व्यवस्था में','अधिक होड़ में','अभ्यास बिना घोषणाओं में'],'सामाजिक-शैक्षिक प्रयत्न के साथ आध्यात्मिक शुद्धि हो।'],
['शाश्वत के बजाय आभासी सत्य क्या है?',['अविकारी आत्मा','कुछ अवधि प्रकट होकर मिट जाने वाला','अस्तित्व का आध्यात्मिक आधार','जन्म-क्षय से परे सत्य'],'आरंभ और अंत स्थायित्व की कसौटी हैं।'],
['मिट्टी के घड़े का उदाहरण क्या दिखाता है?',['हर रूप स्थायी है','नाम ही स्थायी पूर्णता बनाता है','अस्थायी नाम-रूप मूल पदार्थ पर निर्भर है','पदार्थ की जाँच नहीं चाहिए'],'रूप बदलता है, पदार्थ मिट्टी रहता है।'],
['मृगतृष्णा क्या दर्शाती है?',['विश्वसनीय जलस्रोत','विवेक की निरर्थकता','संपत्ति से सुख की निश्चितता','भ्रामक रूप वास्तविक प्यास नहीं बुझाते'],'आकर्षक रूप आत्मज्ञान जैसी स्थायी पूर्णता नहीं देते।']]}
];
